#!/usr/bin/env bash
set -Eeuo pipefail
[[ $# == 1 && $1 =~ ^[a-f0-9]{40}$ ]] || exit 64
sha=$1;n=rum-rate-anything-preview;pod="rat181-phpunit-${sha:0:10}"; created=0
k(){ if command -v k3s >/dev/null 2>&1;then sudo -n k3s kubectl "$@";else kubectl "$@";fi; }
[[ $(k -n "$n" get ingress -o 'jsonpath={.items[*].spec.rules[*].host}') == 'dev-rum-ra.daisycloversoftware.uk' ]] || exit 78
[[ $(git ls-remote https://github.com/DaisyCloverSoftware/rum.git refs/heads/fix/rat-persist-explicit-linked-things-20261122|cut -f1) == "$sha" ]] || exit 78
t=$(mktemp -d); cleanup(){ if [[ $created == 1 ]];then k -n "$n" delete pod "$pod" --wait=false --ignore-not-found;fi;rm -rf "$t"; };trap cleanup EXIT
git -C "$t" init -q;git -C "$t" remote add origin https://github.com/DaisyCloverSoftware/rum.git;git -C "$t" fetch -q --depth=1 origin "$sha";git -C "$t" archive FETCH_HEAD apps/api >"$t/api.tar"
k -n "$n" get deploy rum-api -o json | python3 -c 'import sys,json
cfg=json.load(sys.stdin)["spec"]["template"]["spec"]; name=sys.argv[1];
# No service account token, application envFrom, secrets or persistent volumes. The only inherited setting is registry pull references.
env={"APP_ENV":"testing","APP_KEY":"base64:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","DB_CONNECTION":"pgsql","DB_HOST":"127.0.0.1","DB_PORT":"5432","DB_DATABASE":"rum_test","DB_USERNAME":"rum","DB_PASSWORD":"rum","SESSION_DRIVER":"array","CACHE_STORE":"array","QUEUE_CONNECTION":"sync","MAIL_MAILER":"array"}; e=lambda d:[{"name":k,"value":v} for k,v in d.items()]; res=lambda m:{"requests":{"cpu":"100m","memory":"128Mi"},"limits":{"cpu":"1500m","memory":m}};
s={"automountServiceAccountToken":False,"enableServiceLinks":False,"activeDeadlineSeconds":840,"terminationGracePeriodSeconds":5,"restartPolicy":"Never","imagePullSecrets":cfg.get("imagePullSecrets",[]),"containers":[{"name":"test","image":"ghcr.io/daisycloversoftware/rum-api@sha256:f4e700314dd2fe2b8b6dabee5f640f35b9463d914f8a2be79ff781862a80e978","command":["sleep","840"],"env":e(env),"resources":res("2Gi"),"securityContext":{"allowPrivilegeEscalation":False},"volumeMounts":[{"name":"suite","mountPath":"/work"}]},{"name":"pg","image":"postgres@sha256:eb63372c1e05c755f55fa30cbd07aecc443676fc6c0fa90b9002d01537841e1a","args":["postgres","-c","listen_addresses=127.0.0.1"],"env":e({"POSTGRES_USER":"rum","POSTGRES_PASSWORD":"rum","POSTGRES_DB":"rum_test"}),"resources":res("512Mi"),"volumeMounts":[{"name":"db","mountPath":"/var/lib/postgresql"}],"readinessProbe":{"exec":{"command":["pg_isready","-h","127.0.0.1","-U","rum","-d","rum_test"]},"periodSeconds":3}}],"volumes":[{"name":"suite","emptyDir":{"sizeLimit":"2Gi"}},{"name":"db","emptyDir":{"sizeLimit":"1Gi"}}]}; print(json.dumps({"apiVersion":"v1","kind":"Pod","metadata":{"name":name,"labels":{"task":"rat181-disposable-phpunit"}},"spec":s}))' "$pod" | k -n "$n" create -f -; created=1
k -n "$n" wait --for=condition=Ready "pod/$pod" --timeout=150s || { k -n "$n" get pod "$pod" -o 'jsonpath={.status.containerStatuses[*].state}';exit 1; }
k -n "$n" exec -i "$pod" -c test -- tar -C /work -xf - <"$t/api.tar"
k -n "$n" exec "$pod" -c test -- sh -ec 'cd /work/apps/api; php -r '\''$p=new PDO("pgsql:host=127.0.0.1;dbname=rum_test","rum","rum"); if($p->query("SELECT current_database()")->fetchColumn()!=="rum_test") exit(78);'\''; composer install --no-interaction --prefer-dist --no-progress >/tmp/install.out 2>&1 || { tail -12 /tmp/install.out;exit 1; }; vendor/bin/pint --test app/Models/RatingJourney.php app/Services/StandaloneConnectionIntent.php app/Services/RatingJourneyService.php app/Http/Controllers/Api/V1/StandaloneThingController.php tests/Feature/Entity/StandaloneConnectionIntentTest.php; vendor/bin/phpstan analyse --memory-limit=1G --no-progress; vendor/bin/phpunit --testdox tests/Feature/Entity/StandaloneConnectionIntentTest.php tests/Feature/Entity/RatCommunityContributionTest.php';echo "FOCUSED_DATABASE_LIFECYCLE_PASS=$sha"
